class CharacterInfo:
    def __init__(self, chr, val, idx):
        self.chr = chr
        self.val = val
        self.idx = idx

def swap(chars, vals, i):
    chars[i], chars[len(chars) - i - 1] = chars[len(chars) - i - 1], chars[i]
    vals[i], vals[len(vals) - i - 1] = vals[len(vals) - i - 1], vals[i]

def is_anti_palindrome(chars):
    length = len(chars)
    for i in range(length // 2):
        if chars[i] == chars[length - i - 1]:
            return False
    return True

mismatched_chars = []
char_list = []

for i in range(n // 2):
    if values[i] > values[n - i - 1]:
        swap(characters, values, i)
    ci = CharacterInfo(characters[i], values[i], i)
    if characters[i] == characters[n - i - 1]:
        mismatched_chars.append(ci)
    char_list.append(ci)

char_list.sort(key=lambda c: c.val)

total_diff = 0
if not is_anti_palindrome(characters):
    if len(mismatched_chars) == 1:
        wrong_char = mismatched_chars[0]
        for ci in char_list:
            if ci.chr != wrong_char.chr and characters[n - ci.idx - 1] != wrong_char.chr:
                total_diff = wrong_char.val + ci.val
                break
    elif len(mismatched_chars) > 1:
        count_map = {}
        for ci in mismatched_chars:
            count_map[ci.chr] = count_map.get(ci.chr, 0) + 1
        max_count = max(count_map.values())
        append_list = []
        while max_count * 2 > len(mismatched_chars) + len(append_list):
            max_char = max(count_map, key=count_map.get)
            for ci in char_list:
                if ci.chr != max_char and characters[n - ci.idx - 1] != max_char and ci not in mismatched_chars and ci not in append_list:
                    append_list.append(ci)
                    break
            max_count = max(count_map, key=count_map.get)
        total_diff = sum(c.val for c in mismatched_chars) + sum(c.val for c in append_list)

sum_values = sum(values)
print(sum_values - total_diff)

